solution:
pub type Wrapper[T] = {
  data: T;
}

impl Wrapper[T] {
  fn transform[U](self: &Self, f: fn(T) -> U) -> Wrapper[U] {
    return Wrapper[U]{ data: f(self.data) };
  }

  fn unwrap(self: &Self) -> T {
    return self.data;
  }
}

fn int_to_str(n: Int) -> Str { return n.to_str(); }

fn main() -> Int {
  let w = Wrapper[Int]{ data: 42 };
  let s = w.transform[Str](int_to_str);
  return s.data.len();
}
